import{_ as r,o as a,c as e,a2 as i}from"./chunks/framework.CdvW4CUT.js";const l=JSON.parse('{"title":"副本服新手教學","description":"副本服的新手教學。先完成本教學內容再開始冒險。","frontmatter":{"title":"副本服新手教學","description":"副本服的新手教學。先完成本教學內容再開始冒險。"},"headers":[],"relativePath":"dungeon/teach/index.md","filePath":"dungeon/teach.md"}'),p={name:"dungeon/teach/index.md"};function s(o,t,n,h,c,b){return a(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="新手任務與教學" tabindex="-1">新手任務與教學 <a class="header-anchor" href="#新手任務與教學" aria-label="Permalink to &quot;新手任務與教學&quot;">​</a></h1><p>第一次進入副本服 你位於的空間是 <b>副本服重生點大廳</b><br> 須先完成以下兩項新手教學任務 未來才能接取各項任務 與前往副本服地圖狩獵</p><h3 id="_1-新手任務-導覽-登記成為冒險者" tabindex="-1">1. 新手任務 - [導覽]登記成為冒險者 <a class="header-anchor" href="#_1-新手任務-導覽-登記成為冒險者" aria-label="Permalink to &quot;1. 新手任務 - [導覽]登記成為冒險者&quot;">​</a></h3><p>首先 請向NPC<b>水果攤大叔</b>接取任務 (右鍵點他)<br><img src="https://i.imgur.com/6CArQlK.png" style="width:50%;"></p><p>接下來 會出現一個介面 請點選以接取該任務<br><img src="https://i.imgur.com/1l1xBZc.png" style="width:50%;"></p><p>任務要你去按順序去找以下NPC對話<br> (本次任務需要對話的所有NPC 皆位於副本服大廳)<br><img src="https://i.imgur.com/nbrcLm6.png" style="width:80%;"></p><p>沙漠商隊的人 位於大廳 櫃台右側<br><img src="https://i.imgur.com/QoE3VN8.png" style="width:50%;"></p><p>客家人 位於大廳 回去的門 右側<br><img src="https://i.imgur.com/qznMTCE.png" style="width:50%;"></p><p>邪惡的資本家建商 位於大廳 2樓 (2樓從客家人旁邊的梯子上去)<br><img src="https://i.imgur.com/ya2WhI9.png" style="width:50%;"></p><p>櫃台小姐 位於大廳正前方 櫃台 (任務是要你找左側的對話)<br><img src="https://i.imgur.com/ZIEYIt9.png" style="width:50%;"></p><p>任務完成後 會獲得200元副本幣+1把耐久II鐵劍+10個麵包<br> 並且未來可向水果攤大叔購買武器</p><p>接下來 請接取下一個任務</p><h3 id="_2-新手任務-新手-速成課程" tabindex="-1">2.新手任務 - [新手] 速成課程 <a class="header-anchor" href="#_2-新手任務-新手-速成課程" aria-label="Permalink to &quot;2.新手任務 - [新手] 速成課程&quot;">​</a></h3><p>完成後<br> 向 櫃台小姐(左) 對話 接取任務<br><img src="https://i.imgur.com/wxxhR2s.png" style="width:50%;"></p><p>按照任務需求 至櫃台右側的門 進入 <b>鱷魚洞</b><br> 打死16隻鱷魚之後 回去與NPC對話 即可完成任務<br> 獎勵: 鐵劍x1 麵包x16 500元</p><h3 id="完成任務後" tabindex="-1">完成任務後? <a class="header-anchor" href="#完成任務後" aria-label="Permalink to &quot;完成任務後?&quot;">​</a></h3><p>完成以上新手任務後 即可向各NPC接取任務<br> 並且可至大廳 櫃台後側 的門 進入副本服地圖</p><p>地圖的地形、怪物強度、任務如何解<br> 這部分是設計給玩家自行摸索的</p><p>前期建議你把每個任務都接一接、地形跑一跑、怪物打一打<br> 或是跟別人一起解<br> 久了你就會大概知道怎麼玩了</p><h3 id="任務須知" tabindex="-1">任務須知 <a class="header-anchor" href="#任務須知" aria-label="Permalink to &quot;任務須知&quot;">​</a></h3><p>1.任務流程:<br> 向NPC接取任務→去打怪→打完之後回去對話→即可完成獎勵<br> (需先完成新手教學任務後才可接取任務)<br> 2.重複接取:<br> 任務完成後都會有冷卻時間 冷卻結束後可再次接取 部分任務有 任務點數要求<br> 請輸入 /bs 點擊按鈕查看你目前的任務點數<br> 3.任務接取: 除了大廳NPC有一些任務外 地圖上也有一些NPC是可以接取任務的</p>',21)])])}const m=r(p,[["render",s]]);export{l as __pageData,m as default};
